  "type": "module",
  "license": "MIT",
  "author": {
    "name": "Oskar Hane",
    "email": "oskar.hane@gmail.com",
    "url": "https://github.com/oskarhane"
  },
  "homepage": "https://github.com/oskarhane/oskars.ai/tree/main/plugins/gbuild",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/oskarhane/oskars.ai.git",
    "directory": "plugins/gbuild"
  },
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "skills",
    "agents",
    "reference",
    "cypher",
    "templates"
  ],
  "devDependencies": {
    "@opencode/plugin": "2.0.4"
  },
  "keywords": ["opencode", "opencode-plugin", "gbuild", "graph", "orchestrator", "parallel", "ai", "agent"]
